<script setup lang="ts">import{onMounted,ref}from'vue';import{api,type ApiResponse}from'@whaashop/shared';import type{TagProps}from'element-plus';type PaymentStatus='PENDING'|'PAID';interface Payment{id:number;orderId:number;tradeNo?:string;provider:string;status:PaymentStatus|string;amount:number;updatedAt:string}interface Page<T>{items:T[];total:number}const rows=ref<Payment[]>([]),status=ref<PaymentStatus|''>(''),page=ref(1),size=ref(20),total=ref(0);const statusMap:Record<PaymentStatus,{label:string;type:TagProps['type']}>= {PENDING:{label:'待支付',type:'warning'},PAID:{label:'支付成功',type:'success'}};const providerMap:Record<string,string>={ALIPAY:'支付宝'};async function load(){const{data}=await api.get<ApiResponse<Page<Payment>>>('/admin/payments',{params:{status:status.value||undefined,page:page.value,size:size.value}});rows.value=data.data.items;total.value=data.data.total}function filter(){page.value=1;load()}onMounted(load)</script>
<template><div class="panel"><div class="toolbar"><h2>支付记录</h2><el-select v-model="status" clearable placeholder="全部状态" style="width:160px" @change="filter"><el-option label="待支付" value="PENDING"/><el-option label="支付成功" value="PAID"/></el-select></div><el-table :data="rows"><el-table-column prop="id" label="流水ID"/><el-table-column prop="orderId" label="订单ID"/><el-table-column label="支付渠道"><template #default="s">{{providerMap[s.row.provider]||s.row.provider}}</template></el-table-column><el-table-column prop="tradeNo" label="支付宝交易号" min-width="190"/><el-table-column label="支付状态" width="120"><template #default="s"><el-tag :type="statusMap[s.row.status as PaymentStatus]?.type||'info'">{{statusMap[s.row.status as PaymentStatus]?.label||'未知状态'}}</el-tag></template></el-table-column><el-table-column label="金额"><template #default="s">¥{{s.row.amount}}</template></el-table-column><el-table-column prop="updatedAt" label="更新时间" width="190"/></el-table><el-empty v-if="!rows.length" description="暂无支付记录"/><el-pagination v-model:current-page="page" v-model:page-size="size" :total="total" :page-sizes="[10,20,50]" layout="total, sizes, prev, pager, next, jumper" style="margin-top:18px;justify-content:flex-end" @current-change="load" @size-change="filter"/></div></template>
